begin;
select no_plan();
update private.billing_configuration set enabled=false,access_enabled=true,environment='production';
insert into auth.users(id,email) values('d1000000-0000-4000-8000-000000000154','access-only@example.test');
insert into public.organizations(id,name,slug) values('d2000000-0000-4000-8000-000000000154','Access Only','access-only');
insert into public.organization_members(organization_id,user_id,role,status) values('d2000000-0000-4000-8000-000000000154','d1000000-0000-4000-8000-000000000154','owner','active');
select is(private.effective_billing_access('d2000000-0000-4000-8000-000000000154')->>'plan','free','new account does not receive indefinite legacy trial');
select throws_ok($$select private.require_billing_feature('d2000000-0000-4000-8000-000000000154',null,'radar_charts')$$,'42501','entitlement_required','access-only mode enforces features');
set local role authenticated;
select set_config('request.jwt.claim.sub','d1000000-0000-4000-8000-000000000154',true);
select is(public.get_billing_dashboard('d2000000-0000-4000-8000-000000000154')->>'purchasesEnabled','false','dashboard tells the truth about payment readiness');
select is(public.start_pro_trial('d2000000-0000-4000-8000-000000000154')->'access'->>'source','trial','no-card trial works while purchases disabled');
select throws_ok($$select public.reserve_billing_purchase('d4000000-0000-4000-8000-000000000154','d2000000-0000-4000-8000-000000000154',null,'pro_monthly','stripe')$$,'P0001','billing_not_enabled','trial activation never enables checkout');
reset role;
select lives_ok($$select private.require_billing_feature('d2000000-0000-4000-8000-000000000154',null,'radar_charts')$$,'trial feature works in access-only mode');
select throws_ok($$select private.require_billing_feature('d2000000-0000-4000-8000-000000000154',null,'custom_branding')$$,'42501','entitlement_required','trial does not grant organization features');
update private.pro_trials set starts_at=now()-interval '72 hours',expires_at=now() where organization_id='d2000000-0000-4000-8000-000000000154';
select throws_ok($$select private.require_billing_feature('d2000000-0000-4000-8000-000000000154',null,'radar_charts')$$,'42501','entitlement_required','trial expiry is enforced without payments enabled');
select throws_ok($$select public.apply_billing_snapshot('{}','{}',null)$$,'P0001','billing_not_enabled','provider snapshots stay disabled');
select * from finish(); rollback;
